def longestRunAfterRemoval(nums):
    n = len(nums)
    end = [1] * n
    for i in range(1, n):
        if nums[i - 1] < nums[i]:
            end[i] = end[i - 1] + 1
    start = [1] * n
    for i in range(n - 2, -1, -1):
        if nums[i] < nums[i + 1]:
            start[i] = start[i + 1] + 1
    best = max(end)
    for i in range(1, n - 1):
        if nums[i - 1] < nums[i + 1]:
            best = max(best, end[i - 1] + start[i + 1])
    return best
